sources.JettonMaster.tolk:
tolk 1.5
import "@stdlib/gas-payments"
import "messages"
import "storage"
import "payments"

type MasterMessage = LaunchCreation | ReturnExcessesBack | BurnNotificationForMinter | RequestWalletAddress | RetrySettlement | RefundExcess | MintTokens | SetPause | CloseMinting | SetMetadata | FreezeMetadata | ProposeOwner | AcceptOwner | RenounceOwner | SetRole | FreezeWallet | TopUpTons
type MasterBounce = InternalTransferStep | ServicePayment
fun onBouncedMessage(in: InMessageBounced) {
    in.bouncedBody.skipBouncedPrefix();
    val msg = lazy MasterBounce.fromSlice(in.bouncedBody);
    var s = lazy MasterStorage.load();val config = s.config.load();val e = config.economics.load();
    match (msg) {
        InternalTransferStep => {
            if(s.phase==1){
                assert(in.senderAddress==walletAddress(config.creator,contract.getAddress(),s.controls.load().walletCode) && msg.queryId==queryIdFor(config) && msg.jettonAmount==e.initialSupply) throw 710;
                s.phase=3;s.save();refundAllToCreator(config);
            }else{
                var ctl=s.controls.load();val p=ctl.pendingMints.mustGet(msg.queryId,710);
                assert(in.senderAddress==p.wallet && msg.jettonAmount==p.amount) throw 710;
                s.totalSupply-=p.amount;if(ctl.lifetimeCap){ctl.issued-=p.amount;}ctl.pendingMints.delete(msg.queryId);s.controls=ctl.toCell();s.save();
            }
        }
        ServicePayment => {
            // A bounce only contains the first 256 bits. queryId fits there.
            assert (s.phase == 2 && in.senderAddress == config.treasury && msg.queryId == queryIdFor(config) && e.serviceFee > 0) throw 710;
            s.phase = 4;s.save();
        }
        else => throw 703
    }
}
fun onInternalMessage(in: InMessage) {
    if (in.body.isEmpty()) { return; }
    val msg = lazy MasterMessage.fromSlice(in.body);
    var s = lazy MasterStorage.load();val config = s.config.load();val e = config.economics.load();
    match (msg) {
        LaunchCreation => {
            requireQuery(config, msg.queryId);
            assert (s.phase == 0 && in.senderAddress == config.identity.load().launcher) throw 711;
            if (blockchain.now() > config.deadline) {s.phase = 3;s.save();refundAllToCreator(config);return;}
            assert (in.valueCoins >= e.minimumLaunchValue && e.initialSupply > 0 && e.mintValue >= requiredMintValue()) throw 705;
            assert(e.initialSupply<=s.controls.load().maximum && s.controls.load().issued==0) throw 724;
            var r = s.receipts.load();r.launchLt = in.createdLt;s.receipts = r.toCell();
            s.phase = 1;s.save();
            reserveGramsOnBalance(e.serviceFee + e.recipientTopup + e.storageReserve, RESERVE_MODE_EXACT_AMOUNT);
            val payload = beginCell().storeUint(0,1).endCell().beginParse();
            val mint = createMessage({bounce: BounceMode.Only256BitsOfBody, dest: deployedWallet(config.creator, contract.getAddress(), s.controls.load().walletCode), value: e.mintValue, body: InternalTransferStep {queryId: msg.queryId, jettonAmount: e.initialSupply, transferInitiator: null, sendExcessesTo: contract.getAddress(), forwardTonAmount: 0, forwardPayload: payload}});
            mint.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        ReturnExcessesBack => {
            if(msg.queryId!=queryIdFor(config)){
                var ctl=s.controls.load();val p=ctl.pendingMints.mustGet(msg.queryId,710);assert(in.senderAddress==p.wallet) throw 710;
                ctl.pendingMints.delete(msg.queryId);s.controls=ctl.toCell();s.save();
                val refund=createMessage({bounce:BounceMode.NoBounce,dest:p.requester,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});
                refund.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_IGNORE_ERRORS);return;
            }
            requireQuery(config, msg.queryId);
            assert (in.senderAddress == walletAddress(config.creator, contract.getAddress(), s.controls.load().walletCode)) throw 710;
            if (s.phase == 2 || s.phase == 4) {refundExcessToCreator(config,in.valueCoins);return;}
            assert (s.phase == 1) throw 712;
            s.receipts = settlementReceipt(s.receipts, in.senderAddress, in.createdLt, e.serviceFee);
            s.totalSupply = e.initialSupply;var ctl=s.controls.load();ctl.issued=e.initialSupply;s.controls=ctl.toCell();s.phase = 2;s.save();
            payServiceAndRefund(config);
        }
        BurnNotificationForMinter => {
            assert (s.controls.load().burnable && (s.phase == 2 || s.phase == 4) && in.senderAddress == walletAddress(msg.burnInitiator, contract.getAddress(), s.controls.load().walletCode) && msg.jettonAmount > 0 && s.totalSupply >= msg.jettonAmount) throw 713;
            s.totalSupply -= msg.jettonAmount;s.save();
            if (msg.sendExcessesTo != null) {
                val excess = createMessage({bounce: BounceMode.NoBounce, dest: msg.sendExcessesTo, value: 0, body: ReturnExcessesBack {queryId: msg.queryId}});
                excess.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_IGNORE_ERRORS);
            }
        }
        RequestWalletAddress => {
            val owner = msg.includeOwnerAddress ? msg.ownerAddress.toCell() : null;
            val addr = msg.ownerAddress.getWorkchain() == 0 ? walletAddress(msg.ownerAddress, contract.getAddress(), s.controls.load().walletCode) : null;
            val response = createMessage({bounce: BounceMode.NoBounce,dest: in.senderAddress,value:0,body:ResponseWalletAddress {queryId: msg.queryId,jettonWalletAddress: addr,ownerAddress: owner}});
            response.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        RetrySettlement => {
            requireQuery(config,msg.queryId);
            assert (in.valueCoins >= mintReceiptValue() + calculateGasFee(0,25000)) throw 705;
            if (s.phase == 1) {
                val retry = createMessage({bounce: BounceMode.Only256BitsOfBody,dest:walletAddress(config.creator,contract.getAddress(),s.controls.load().walletCode),value:0,body:RetryMintReceipt {queryId:msg.queryId}});
                retry.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
            } else {
                assert (s.phase == 4) throw 712;
                s.receipts = settlementReceipt(s.receipts, in.senderAddress, in.createdLt, e.serviceFee);
                s.phase=2;s.save();payServiceAndRefund(config);
            }
        }
        RefundExcess => {
            requireQuery(config,msg.queryId);
            assert (s.phase==2) throw 712;
            refundExcessToCreator(config,in.valueCoins);
        }
        MintTokens => {
            var ctl=s.controls.load();requireRole(ctl,in.senderAddress,1);
            assert(s.phase==2 && ctl.mintable && !ctl.paused && msg.recipient.getWorkchain()==0 && msg.amount>0 && s.totalSupply+msg.amount<=ctl.maximum && (!ctl.lifetimeCap || ctl.issued+msg.amount<=ctl.maximum)) throw 724;
            assert(msg.queryId!=queryIdFor(config) && in.valueCoins>=requiredMintValue()+calculateGasFee(0,35000)+calculateForwardFee(0,30000,128)) throw 705;
            assert(!ctl.pendingMints.exists(msg.queryId)) throw 723;s.totalSupply+=msg.amount;ctl.issued=min(1329227995784915872903807060280344575,ctl.issued+msg.amount) as coins;ctl.pendingMints.set(msg.queryId,PendingMint{wallet:walletAddress(msg.recipient,contract.getAddress(),ctl.walletCode),amount:msg.amount,requester:in.senderAddress});s.controls=ctl.toCell();s.save();
            val mint=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:deployedWallet(msg.recipient,contract.getAddress(),s.controls.load().walletCode),value:0,body:InternalTransferStep{queryId:msg.queryId,jettonAmount:msg.amount,transferInitiator:null,sendExcessesTo:contract.getAddress(),forwardTonAmount:0,forwardPayload:beginCell().storeUint(0,1).endCell().beginParse()}});
            mint.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        SetPause => {var ctl=s.controls.load();requireRole(ctl,in.senderAddress,2);assert(ctl.pausable) throw 724;ctl.paused=msg.paused;s.controls=ctl.toCell();s.save();refundCommandBudget(config,in.senderAddress,in.valueCoins);}
        CloseMinting => {var ctl=s.controls.load();requireOwner(ctl,in.senderAddress);ctl.mintable=false;s.controls=ctl.toCell();s.save();refundCommandBudget(config,in.senderAddress,in.valueCoins);}
        SetMetadata => {var ctl=s.controls.load();requireRole(ctl,in.senderAddress,4);assert(ctl.metadataMutable) throw 724;s.content=msg.content;s.save();refundCommandBudget(config,in.senderAddress,in.valueCoins);}
        FreezeMetadata => {var ctl=s.controls.load();requireOwner(ctl,in.senderAddress);ctl.metadataMutable=false;s.controls=ctl.toCell();s.save();refundCommandBudget(config,in.senderAddress,in.valueCoins);}
        ProposeOwner => {var ctl=s.controls.load();requireOwner(ctl,in.senderAddress);assert(msg.owner.getWorkchain()==0) throw 701;ctl.pendingOwner=msg.owner;s.controls=ctl.toCell();s.save();refundCommandBudget(config,in.senderAddress,in.valueCoins);}
        AcceptOwner => {assert(s.phase==2||s.phase==4) throw 711;var ctl=s.controls.load();assert(ctl.pendingOwner!=null && in.senderAddress==ctl.pendingOwner!) throw 710;ctl.owner=in.senderAddress;ctl.pendingOwner=null;ctl.roles=createEmptyMap();s.controls=ctl.toCell();s.save();refundCommandBudget(config,in.senderAddress,in.valueCoins);}
        RenounceOwner => {var ctl=s.controls.load();requireOwner(ctl,in.senderAddress);assert(!ctl.paused && !ctl.freezable) throw 724;ctl.owner=null;ctl.pendingOwner=null;ctl.roles=createEmptyMap();ctl.mintable=false;ctl.metadataMutable=false;ctl.freezable=false;s.controls=ctl.toCell();s.save();refundCommandBudget(config,in.senderAddress,in.valueCoins);}
        SetRole => {var ctl=s.controls.load();requireOwner(ctl,in.senderAddress);assert(msg.roles<=15 && msg.account.getWorkchain()==0) throw 724;if(msg.roles==0){ctl.roles.delete(msg.account);}else{ctl.roles.set(msg.account,msg.roles);}s.controls=ctl.toCell();s.save();refundCommandBudget(config,in.senderAddress,in.valueCoins);}
        FreezeWallet => {
            val ctl=s.controls.load();requireRole(ctl,in.senderAddress,8);assert(ctl.freezable && msg.account.getWorkchain()==0 && in.valueCoins>=grams("0.1")) throw 724;
            val freeze=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:deployedWallet(msg.account,contract.getAddress(),s.controls.load().walletCode),value:0,body:SetWalletFrozen{queryId:msg.queryId,frozen:msg.frozen,response:in.senderAddress}});
            freeze.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        TopUpTons => {}
        else => throw 703
    }
}
get fun get_jetton_data(): (int, bool, address?, cell, cell) {
    val s=lazy MasterStorage.load();val ctl=s.controls.load();return (s.totalSupply,ctl.mintable,ctl.owner,s.content,s.controls.load().walletCode);
}
get fun get_wallet_address(owner: address): address {
    val s=lazy MasterStorage.load();return walletAddress(owner,contract.getAddress(),s.controls.load().walletCode);
}
get fun get_creation_state(): (int,int,int) {
    val s=lazy MasterStorage.load();val c=s.config.load();val e=c.economics.load();return(s.phase,c.quoteId,e.initialSupply);
}

fun requireOwner(c:TokenControls,sender:address){assert(MasterStorage.load().phase==2||MasterStorage.load().phase==4) throw 711;assert(c.owner!=null && sender==c.owner!) throw 710;}
fun requireRole(c:TokenControls,sender:address,bit:int){assert(MasterStorage.load().phase==2||MasterStorage.load().phase==4) throw 711;if(c.owner!=null && sender==c.owner!){return;}val r=c.roles.get(sender);assert(r.isFound && (r.loadValue() & bit)!=0 && c.owner!=null) throw 710;}
get fun get_token_controls():cell {return MasterStorage.load().controls;}

sources.JettonWallet.tolk:
tolk 1.5
import "@stdlib/gas-payments"
import "messages"
import "storage"
import "payments"

// TEP-74 wallet. A master-origin mint credits the supply and emits a mandatory
// standard Excesses receipt in the SAME wallet transaction. Failure to emit it
// rolls the credit back. Ordinary transfers/burns keep standard behavior.
type WalletMessage = AskToTransfer | InternalTransferStep | AskToBurn | RetryMintReceipt | SetWalletFrozen | TopUpTons
type WalletBounce = InternalTransferStep | BurnNotificationForMinter | ReturnExcessesBack
fun onBouncedMessage(in: InMessageBounced) {
    in.bouncedBody.skipBouncedPrefix();
    val msg = lazy WalletBounce.fromSlice(in.bouncedBody);
    var s = lazy WalletStorage.load();
    match (msg) {
        InternalTransferStep => { s.jettonBalance += msg.jettonAmount; s.save(); }
        BurnNotificationForMinter => { assert (in.senderAddress == s.minterAddress) throw 702; s.jettonBalance += msg.jettonAmount; s.save(); }
        ReturnExcessesBack => { assert (in.senderAddress == s.minterAddress && msg.queryId == s.mintQueryId) throw 702; }
        else => throw 703
    }
}
fun sendMintReceipt(s: WalletStorage) {
    reserveGramsOnBalance(walletStorageReserve(), RESERVE_MODE_EXACT_AMOUNT);
    val receipt = createMessage({bounce: BounceMode.Only256BitsOfBody, dest: s.minterAddress, value: mintReceiptValue(), body: ReturnExcessesBack {queryId: s.mintQueryId}});
    receipt.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
    val unused = createMessage({bounce: BounceMode.NoBounce, dest: s.ownerAddress, value: 0, body: ReturnExcessesBack {queryId: s.mintQueryId}});
    unused.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);
}
fun onInternalMessage(in: InMessage) {
    if (in.body.isEmpty()) { return; }
    val msg = lazy WalletMessage.fromSlice(in.body);
    var s = lazy WalletStorage.load();
    match (msg) {
        InternalTransferStep => {
            checkForwardPayload(msg.forwardPayload);
            if (in.senderAddress == s.minterAddress) {
                assert (msg.jettonAmount > 0 && msg.forwardTonAmount == 0 && msg.sendExcessesTo != null) throw 704;
                assert (in.valueCoins >= requiredMintValue()) throw 705;
                s.jettonBalance += msg.jettonAmount;
                if(s.mintedAmount==0){s.mintQueryId=msg.queryId;s.mintedAmount=msg.jettonAmount;}
                s.save();
                reserveGramsOnBalance(walletStorageReserve(),RESERVE_MODE_EXACT_AMOUNT);
                val ack=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:s.minterAddress,value:mintReceiptValue(),body:ReturnExcessesBack{queryId:msg.queryId}});
                ack.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
                val unused=createMessage({bounce:BounceMode.NoBounce,dest:s.ownerAddress,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});
                unused.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);
                return;
            }
            assert (msg.transferInitiator != null && in.senderAddress == walletAddress(msg.transferInitiator!, s.minterAddress, contract.getCode())) throw 706;
            s.jettonBalance += msg.jettonAmount;
            s.save();
            if (msg.forwardTonAmount > 0) {
                val notify = createMessage({bounce: BounceMode.NoBounce, dest: s.ownerAddress, value: msg.forwardTonAmount, body: TransferNotificationForRecipient {queryId: msg.queryId, jettonAmount: msg.jettonAmount, transferInitiator: msg.transferInitiator, forwardPayload: msg.forwardPayload}});
                notify.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
            }
            if (msg.sendExcessesTo != null) {
                reserveGramsOnBalance(max(walletStorageReserve(), contract.getOriginalBalance() - in.valueCoins + contract.getStorageDuePayment()), RESERVE_MODE_AT_MOST);
                val excess = createMessage({bounce: BounceMode.NoBounce, dest: msg.sendExcessesTo, value: 0, body: ReturnExcessesBack {queryId: msg.queryId}});
                excess.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);
            }
        }
        AskToTransfer => {
            assert (!s.frozen && in.senderAddress == s.ownerAddress && msg.transferRecipient.getWorkchain() == 0) throw 707;
            checkForwardPayload(msg.forwardPayload);
            assert (msg.jettonAmount > 0 && s.jettonBalance >= msg.jettonAmount) throw 708;
            val minValue = walletStorageReserve() + calculateGasFee(0, 50000) + calculateForwardFee(0, 30000, 128) * 3 + msg.forwardTonAmount;
            assert (in.valueCoins > minValue) throw 705;
            s.jettonBalance -= msg.jettonAmount;
            s.save();
            val transfer = createMessage({bounce: BounceMode.Only256BitsOfBody, dest: deployedWallet(msg.transferRecipient, s.minterAddress, contract.getCode()), value: 0, body: InternalTransferStep {queryId: msg.queryId, jettonAmount: msg.jettonAmount, transferInitiator: s.ownerAddress, sendExcessesTo: msg.sendExcessesTo, forwardTonAmount: msg.forwardTonAmount, forwardPayload: msg.forwardPayload}});
            transfer.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        AskToBurn => {
            assert (in.senderAddress == s.ownerAddress) throw 707;
            assert (msg.jettonAmount > 0 && s.jettonBalance >= msg.jettonAmount) throw 708;
            assert (in.valueCoins > calculateGasFee(0, 50000) + calculateForwardFee(0, 2000, 8)) throw 705;
            s.jettonBalance -= msg.jettonAmount;
            s.save();
            val burn = createMessage({bounce: BounceMode.Only256BitsOfBody, dest: s.minterAddress, value: 0, body: BurnNotificationForMinter {queryId: msg.queryId, jettonAmount: msg.jettonAmount, burnInitiator: s.ownerAddress, sendExcessesTo: msg.sendExcessesTo}});
            burn.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        RetryMintReceipt => {
            assert (s.mintedAmount > 0 && msg.queryId == s.mintQueryId) throw 709;
            assert (in.valueCoins >= mintReceiptValue() + calculateGasFee(0, 25000)) throw 705;
            sendMintReceipt(s);
        }
        SetWalletFrozen => {assert(in.senderAddress==s.minterAddress) throw 710;s.frozen=msg.frozen;s.save();reserveGramsOnBalance(max(walletStorageReserve(),contract.getOriginalBalance()-in.valueCoins+contract.getStorageDuePayment()),RESERVE_MODE_AT_MOST);val refund=createMessage({bounce:BounceMode.NoBounce,dest:msg.response,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});refund.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);}
        TopUpTons => {}
        else => throw 703
    }
}
get fun get_wallet_data(): (int, address, address, cell) {
    val s = lazy WalletStorage.load();
    return (s.jettonBalance, s.ownerAddress, s.minterAddress, contract.getCode());
}
get fun get_mint_receipt(): (int, int) {
    val s = lazy WalletStorage.load();return (s.mintQueryId, s.mintedAmount);
}

get fun get_wallet_frozen():bool{return WalletStorage.load().frozen;}

sources.NftCollection.tolk:
tolk 1.5
import "@stdlib/gas-payments"
import "messages"
import "storage"
import "payments"

type CollectionMessage = LaunchCreation | MintItem | FactoryReceipt | SetPause | CloseMinting | SetMetadata | FreezeMetadata | EditItem | SetRoyalty | FreezeRoyalty | RequestRoyalty | ProposeOwner | AcceptOwner | RenounceOwner | SetRole | RetrySettlement | TopUpTons
type CollectionBounce = ServicePayment | InitializeItem | SetItemMetadata
fun onBouncedMessage(in:InMessageBounced){
    in.bouncedBody.skipBouncedPrefix();val msg=lazy CollectionBounce.fromSlice(in.bouncedBody);
    var s=CollectionStorage.load();val c=s.config.load();
    match(msg){
        ServicePayment=>{assert(s.phase==2 && in.senderAddress==c.treasury && msg.queryId==queryIdFor(c)) throw 710;s.phase=4;s.save();}
        InitializeItem=>{val ctl=s.controls.load();val p=ctl.pending.mustGet(msg.queryId,710);assert(in.senderAddress==collectionItem(p.index,contract.getAddress(),s.config,ctl.itemCode).calculateAddress()) throw 710;val refund=createMessage({bounce:BounceMode.NoBounce,dest:p.requester,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});refund.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_IGNORE_ERRORS);}
        SetItemMetadata=>{var ctl=s.controls.load();val p=ctl.pending.mustGet(msg.queryId,710);assert(in.senderAddress==collectionItem(p.index,contract.getAddress(),s.config,ctl.itemCode).calculateAddress()) throw 710;ctl.pending.delete(msg.queryId);s.controls=ctl.toCell();s.save();val refund=createMessage({bounce:BounceMode.NoBounce,dest:p.requester,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});refund.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_IGNORE_ERRORS);}
        else=>throw 703
    }
}
fun owner(ctl:CollectionControls,sender:address){assert(ctl.owner!=null && sender==ctl.owner!) throw 710;assert(CollectionStorage.load().phase==2||CollectionStorage.load().phase==4) throw 711;}
fun role(ctl:CollectionControls,sender:address,bit:int){assert(CollectionStorage.load().phase==2||CollectionStorage.load().phase==4) throw 711;if(ctl.owner!=null && sender==ctl.owner!){return;}val r=ctl.roles.get(sender);assert(ctl.owner!=null && r.isFound && (r.loadValue() & bit)!=0) throw 710;}
fun onInternalMessage(in:InMessage){
    if(in.body.isEmpty()){return;}val msg=lazy CollectionMessage.fromSlice(in.body);
    var s=CollectionStorage.load();val c=s.config.load();var ctl=s.controls.load();
    match(msg){
        LaunchCreation=>{
            requireQuery(c,msg.queryId);assert(s.phase==0 && in.senderAddress==c.identity.load().launcher) throw 710;
            if(blockchain.now()>c.deadline){s.phase=3;s.save();refundAllToCreator(c);return;}
            assert(in.valueCoins>=c.economics.load().minimumLaunchValue && ctl.maximum>0 && ctl.royaltyNumerator<=10000) throw 705;
            var r=s.receipts.load();r.launchLt=in.createdLt;s.receipts=settlementReceipt(r.toCell(),in.senderAddress,in.createdLt,c.economics.load().serviceFee);s.phase=2;s.save();payServiceAndRefund(c);
        }
        MintItem=>{
            assert(s.phase==2 && ctl.mintable && !ctl.paused && in.valueCoins>=grams("0.15") && msg.recipient.getWorkchain()==0) throw 724;role(ctl,in.senderAddress,1);
            var index=s.nextIndex;
            val existing=ctl.pending.get(msg.queryId);
            if(existing.isFound){val p=existing.loadValue();assert(p.mint && msg.expectedIndex==p.index && p.recipient==msg.recipient && p.content.hash()==msg.content.hash()) throw 723;index=p.index;}
            else{assert(msg.expectedIndex==index) throw 723;assert(index<ctl.maximum && index<18446744073709551615) throw 724;ctl.pending.set(msg.queryId,PendingItem{index,recipient:msg.recipient,requester:in.senderAddress,content:msg.content,mint:true,mutable:ctl.metadataMutable});s.nextIndex+=1;s.controls=ctl.toCell();s.save();}
            val mint=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:collectionItem(index,contract.getAddress(),s.config,ctl.itemCode),value:0,body:InitializeItem{queryId:msg.queryId,owner:msg.recipient,content:msg.content,authority:contract.getAddress(),mutable:ctl.pending.mustGet(msg.queryId,710).mutable}});
            mint.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        FactoryReceipt=>{if(!ctl.pending.exists(msg.queryId)){return;}val p=ctl.pending.mustGet(msg.queryId,710);assert(in.senderAddress==collectionItem(p.index,contract.getAddress(),s.config,ctl.itemCode).calculateAddress()) throw 710;ctl.pending.delete(msg.queryId);s.controls=ctl.toCell();s.save();refundCommandBudget(c,p.requester,in.valueCoins);}
        SetPause=>{role(ctl,in.senderAddress,2);ctl.paused=msg.paused;s.controls=ctl.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        CloseMinting=>{owner(ctl,in.senderAddress);ctl.mintable=false;s.controls=ctl.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        SetMetadata=>{role(ctl,in.senderAddress,4);assert(ctl.metadataMutable) throw 724;s.content=msg.content;s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        FreezeMetadata=>{owner(ctl,in.senderAddress);ctl.metadataMutable=false;s.controls=ctl.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        EditItem=>{
            role(ctl,in.senderAddress,4);assert(ctl.metadataMutable && msg.index<s.nextIndex && in.valueCoins>=grams("0.05")) throw 724;
            assert(!ctl.pending.exists(msg.queryId)) throw 723;ctl.pending.set(msg.queryId,PendingItem{index:msg.index,recipient:in.senderAddress,requester:in.senderAddress,content:msg.content,mint:false,mutable:!msg.freeze});s.controls=ctl.toCell();s.save();
            val change=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:collectionItem(msg.index,contract.getAddress(),s.config,ctl.itemCode).calculateAddress(),value:0,body:SetItemMetadata{queryId:msg.queryId,content:msg.content,mutable:!msg.freeze}});
            change.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        SetRoyalty=>{role(ctl,in.senderAddress,8);assert(ctl.royaltyMutable && msg.numerator<=10000 && msg.recipient.getWorkchain()==0) throw 724;ctl.royaltyNumerator=msg.numerator;ctl.royaltyRecipient=msg.recipient;s.controls=ctl.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        FreezeRoyalty=>{owner(ctl,in.senderAddress);ctl.royaltyMutable=false;s.controls=ctl.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        RequestRoyalty=>{val reply=createMessage({bounce:BounceMode.NoBounce,dest:in.senderAddress,value:0,body:RoyaltyResponse{queryId:msg.queryId,numerator:ctl.royaltyNumerator,denominator:10000,recipient:ctl.royaltyRecipient}});reply.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);}
        ProposeOwner=>{owner(ctl,in.senderAddress);assert(msg.owner.getWorkchain()==0) throw 701;ctl.pendingOwner=msg.owner;s.controls=ctl.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        AcceptOwner=>{assert(s.phase==2||s.phase==4) throw 711;assert(ctl.pendingOwner!=null && in.senderAddress==ctl.pendingOwner!) throw 710;ctl.owner=in.senderAddress;ctl.pendingOwner=null;ctl.roles=createEmptyMap();s.controls=ctl.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        RenounceOwner=>{owner(ctl,in.senderAddress);assert(!ctl.paused) throw 724;ctl.owner=null;ctl.pendingOwner=null;ctl.mintable=false;ctl.metadataMutable=false;ctl.royaltyMutable=false;ctl.roles=createEmptyMap();s.controls=ctl.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        SetRole=>{owner(ctl,in.senderAddress);assert(msg.roles<=15 && msg.account.getWorkchain()==0) throw 724;if(msg.roles==0){ctl.roles.delete(msg.account);}else{ctl.roles.set(msg.account,msg.roles);}s.controls=ctl.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        RetrySettlement=>{requireQuery(c,msg.queryId);assert(s.phase==4 && in.valueCoins>=grams("0.1")) throw 712;s.receipts=settlementReceipt(s.receipts,in.senderAddress,in.createdLt,c.economics.load().serviceFee);s.phase=2;s.save();payServiceAndRefund(c);}
        TopUpTons=>{}
        else=>throw 703
    }
}
get fun get_collection_data():(int,cell,address?){val s=CollectionStorage.load();return(s.nextIndex,s.content,s.controls.load().owner);}
get fun get_nft_address_by_index(index:uint64):address{val s=CollectionStorage.load();return collectionItem(index,contract.getAddress(),s.config,s.controls.load().itemCode).calculateAddress();}
get fun get_nft_content(index:uint64,individual:cell):cell{return individual;}
get fun royalty_params():(int,int,address){val c=CollectionStorage.load().controls.load();return(c.royaltyNumerator,10000,c.royaltyRecipient);}
get fun get_collection_controls():cell{return CollectionStorage.load().controls;}

