tolk 1.5
import "@stdlib/gas-payments"
import "messages"
import "storage"
import "payments"

type NftMessage = LaunchCreation | AskToChangeOwnership | RequestStaticData | RetrySettlement | RefundExcess | InitializeItem | SetItemMetadata | SetMetadata | FreezeMetadata | BurnItem | TopUpTons
fun onBouncedMessage(in: InMessageBounced) {
    in.bouncedBody.skipBouncedPrefix();
    val msg=lazy ServicePayment.fromSlice(in.bouncedBody);
    var s=lazy NftStorage.load();val c=s.config.load();
    assert((s.phase==2||s.phase==5) && in.senderAddress==c.treasury && msg.queryId==queryIdFor(c)) throw 710;
    s.phase=s.phase==5?6:4;s.save();
}
fun onInternalMessage(in: InMessage) {
    if(in.body.isEmpty()) {return;}
    val msg=lazy NftMessage.fromSlice(in.body);
    var s=lazy NftStorage.load();val c=s.config.load();val e=c.economics.load();
    match(msg) {
        LaunchCreation => {
            requireQuery(c,msg.queryId);
            assert(s.phase==0 && s.details.load().collection==null && in.senderAddress==c.identity.load().launcher) throw 711;
            if(blockchain.now()>c.deadline) {s.phase=3;s.save();refundAllToCreator(c);return;}
            assert(in.valueCoins>=e.minimumLaunchValue && e.initialSupply==1) throw 705;
            var r = s.receipts.load();r.launchLt = in.createdLt;s.receipts = r.toCell();
            s.receipts = settlementReceipt(s.receipts, in.senderAddress, in.createdLt, e.serviceFee);
            s.phase=2;s.ownerAddress=c.creator;s.save();payServiceAndRefund(c);
        }
        AskToChangeOwnership => {
            assert((s.phase==2||s.phase==4) && in.senderAddress==s.ownerAddress && msg.newOwnerAddress.getWorkchain()==0) throw 707;
            checkForwardPayload(msg.forwardPayload);
            assert(in.valueCoins>msg.forwardTonAmount+calculateGasFee(0,25000)+in.originalForwardFee*3) throw 705;
            s.ownerAddress=msg.newOwnerAddress;s.save();
            reserveGramsOnBalance(max(e.storageReserve,contract.getOriginalBalance()-in.valueCoins),RESERVE_MODE_AT_MOST);
            if(msg.forwardTonAmount>0) {
                val notify=createMessage({bounce:BounceMode.NoBounce,dest:msg.newOwnerAddress,value:msg.forwardTonAmount,body:NotificationForNewOwner {queryId:msg.queryId,oldOwnerAddress:in.senderAddress,forwardPayload:msg.forwardPayload}});
                notify.send(SEND_MODE_PAY_FEES_SEPARATELY);
            }
            if(msg.sendExcessesTo!=null) {
                val excess=createMessage({bounce:BounceMode.NoBounce,dest:msg.sendExcessesTo,value:0,body:ReturnExcessesBack {queryId:msg.queryId}});
                excess.send(SEND_MODE_CARRY_ALL_BALANCE|SEND_MODE_IGNORE_ERRORS);
            }
        }
        RequestStaticData => {
            val reply=createMessage({bounce:BounceMode.NoBounce,dest:in.senderAddress,value:0,body:ResponseStaticData {queryId:msg.queryId,itemIndex:s.details.load().index as uint256,collectionAddress:s.details.load().collection}});
            reply.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
        }
        RetrySettlement => {
            requireQuery(c,msg.queryId);
            assert((s.phase==4||s.phase==6) && in.valueCoins>=mintReceiptValue()+calculateGasFee(0,25000)) throw 712;
            s.receipts = settlementReceipt(s.receipts, in.senderAddress, in.createdLt, e.serviceFee);
            s.phase=s.phase==6?5:2;s.save();payServiceAndRefund(c);
        }
        RefundExcess => {requireQuery(c,msg.queryId);assert(s.phase==2) throw 712;refundExcessToCreator(c,in.valueCoins);}
        InitializeItem => {
            var d=s.details.load();assert(d.collection!=null && in.senderAddress==d.collection!) throw 710;
            if(s.phase==0){s.phase=2;s.ownerAddress=msg.owner;s.content=msg.content;d.metadataAuthority=msg.authority;d.mutable=msg.mutable;d.initialMintQueryId=msg.queryId;s.details=d.toCell();s.save();}
            else{assert((s.phase==2||s.phase==5) && msg.queryId==d.initialMintQueryId) throw 724;}
            reserveGramsOnBalance(max(grams("0.03"),calculateStorageFee(0,5*365*86400,16000,64)),RESERVE_MODE_EXACT_AMOUNT);
            val ack=createMessage({bounce:BounceMode.NoBounce,dest:in.senderAddress,value:grams("0.015"),body:FactoryReceipt{queryId:msg.queryId}});ack.send(SEND_MODE_PAY_FEES_SEPARATELY);
            val excess=createMessage({bounce:BounceMode.NoBounce,dest:s.ownerAddress,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});excess.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);
        }
        SetItemMetadata => {
            var d=s.details.load();assert(s.phase==2 && d.collection!=null && in.senderAddress==d.collection! && d.metadataAuthority!=null && in.senderAddress==d.metadataAuthority! && d.mutable) throw 710;
            s.content=msg.content;d.mutable=msg.mutable;s.details=d.toCell();s.save();
            reserveGramsOnBalance(max(grams("0.03"),contract.getOriginalBalance()-in.valueCoins+contract.getStorageDuePayment()),RESERVE_MODE_AT_MOST);
            val ack=createMessage({bounce:BounceMode.NoBounce,dest:in.senderAddress,value:0,body:FactoryReceipt{queryId:msg.queryId}});ack.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        SetMetadata => {val d=s.details.load();assert(s.phase==2 && d.mutable && d.metadataAuthority!=null && in.senderAddress==d.metadataAuthority!) throw 710;s.content=msg.content;s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        FreezeMetadata => {var d=s.details.load();assert(s.phase==2 && d.metadataAuthority!=null && in.senderAddress==d.metadataAuthority!) throw 710;d.mutable=false;d.metadataAuthority=null;s.details=d.toCell();s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        BurnItem => {assert((s.phase==2||s.phase==4) && in.senderAddress==s.ownerAddress && s.details.load().burnable) throw 710;s.phase=s.phase==4?6:5;s.save();refundCommandBudget(c,in.senderAddress,in.valueCoins);}
        TopUpTons => {}
        else => throw 703
    }
}
get fun get_nft_data(): (bool,int,address?,address?,cell) {
    val s=lazy NftStorage.load();val d=s.details.load();return(s.phase==2||s.phase==4,d.index,d.collection,s.phase==0||s.phase==3||s.phase==5||s.phase==6?null:s.ownerAddress,s.content);
}
get fun get_creation_state(): (int,int,int) {
    val s=lazy NftStorage.load();val c=s.config.load();return(s.phase,c.quoteId,1);
}

sources.SuiteFactory.tolk:
tolk 1.5
import "@stdlib/gas-payments"
import "messages"

// The factory is immutable. It authorizes StateInit cells; each child retains
// the exact quoted payment until its own creation/funding acknowledgement.
struct PendingLaunch { creator: address; asset: address }
struct PendingOwner { owner: address? }
struct FactoryStorage {
    owner: address
    pendingOwner: Cell<PendingOwner>
    treasury: address
    signer: uint256
    paused: bool
    pending: map<uint64, PendingLaunch>
}
type FactoryMessage = FactoryLaunch | FactoryReceipt | ConfigureService | ProposeOwner | AcceptOwner | TopUpTons
fun onBouncedMessage(in: InMessageBounced) {
    in.bouncedBody.skipBouncedPrefix();
    val msg = lazy LaunchCreation.fromSlice(in.bouncedBody);
    var s = FactoryStorage.fromCell(contract.getData());
    val p = s.pending.mustGet(msg.queryId, 721);
    assert (in.senderAddress == p.asset) throw 710;
    s.pending.delete(msg.queryId);contract.setData(s.toCell());
    val refund = createMessage({bounce:BounceMode.NoBounce,dest:p.creator,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});
    refund.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_IGNORE_ERRORS);
}
fun onInternalMessage(in: InMessage) {
    if (in.body.isEmpty()) { return; }
    val msg = lazy FactoryMessage.fromSlice(in.body);
    var s = FactoryStorage.fromCell(contract.getData());
    match (msg) {
        FactoryLaunch => {
            val network=blockchain.configParam(19);
            assert(network!=null && network!.beginParse().loadInt(32)==-239) throw 725;
            val t = msg.terms.load();val e = t.endpoints.load();val code = t.template.load();
            assert (!s.paused && t.domain == 0x52544332 && t.deadline >= blockchain.now() && t.deadline <= blockchain.now()+300) throw 711;
            assert (e.factory == contract.getAddress() && e.treasury == s.treasury && in.senderAddress == t.creator) throw 710;
            assert (isSignatureValid(msg.terms.hash(), msg.signature as slice, s.signer)) throw 722;
            val id = (t.quoteId >> 192) as uint64;
            assert (!s.pending.exists(id)) throw 723;
            val deploy: AutoDeployAddress = {workchain:0,stateInit:{code:code.code,data:code.data}};
            assert (in.valueCoins >= t.value + grams("0.05") + calculateGasFee(0,40000) + calculateForwardFee(0,100000,400)) throw 705;
            reserveGramsOnBalance(max(grams("0.1"),contract.getOriginalBalance()-in.valueCoins+grams("0.05")),RESERVE_MODE_EXACT_AMOUNT);
            s.pending.set(id,PendingLaunch{creator:t.creator,asset:deploy.calculateAddress()});contract.setData(s.toCell());
            val launch = createMessage({bounce:BounceMode.Only256BitsOfBody,dest:deploy,value:0,body:LaunchCreation{queryId:id}});
            launch.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }
        FactoryReceipt => {
            if(!s.pending.exists(msg.queryId)){return;}
            val p = s.pending.mustGet(msg.queryId,721);assert (in.senderAddress == p.asset) throw 710;
            s.pending.delete(msg.queryId);contract.setData(s.toCell());
            val refund = createMessage({bounce:BounceMode.NoBounce,dest:p.creator,value:grams("0.03"),body:ReturnExcessesBack{queryId:msg.queryId}});
            refund.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_IGNORE_ERRORS);
        }
        ConfigureService => {
            assert (in.senderAddress == s.owner && msg.treasury.getWorkchain() == 0 && msg.signer != 0) throw 710;
            s.treasury=msg.treasury;s.signer=msg.signer;s.paused=msg.paused;contract.setData(s.toCell());
        }
        ProposeOwner => {assert(in.senderAddress==s.owner && msg.owner.getWorkchain()==0) throw 710;s.pendingOwner=PendingOwner{owner:msg.owner}.toCell();contract.setData(s.toCell());}
        AcceptOwner => {assert(s.pendingOwner.load().owner!=null && in.senderAddress==s.pendingOwner.load().owner!) throw 710;s.owner=in.senderAddress;s.pendingOwner=PendingOwner{owner:null}.toCell();contract.setData(s.toCell());}
        TopUpTons => {}
        else => throw 703
    }
}
get fun get_service_data(): (address,address?,address,int,bool,int) {
    val s=FactoryStorage.fromCell(contract.getData());return(s.owner,s.pendingOwner.load().owner,s.treasury,s.signer,s.paused,2);
}

sources.Vesting.tolk:
tolk 1.5
import "@stdlib/gas-payments"
import "messages"
import "storage"
import "payments"

struct EscrowTerms {
    kind: uint8 // 0 TON, 1 jetton, 2 NFT; 3 jetton time lock
    beneficiary: address
    asset: address?
    start: uint32
    cliff: uint32
    end: uint32
    principal: coins
}
struct EscrowStorage {
    phase: uint8 // 0 new, 1 awaiting asset, 2 funded, 3 cancelled, 4 fee bounced
    claimed: coins
    wallet: address?
    returnedFee: coins
    config: Cell<CreationConfig>
    terms: Cell<EscrowTerms>
    receipts: Cell<CreationReceipts>
}
type EscrowMessage = LaunchCreation | TransferNotificationForRecipient | NotificationForNewOwner | ReleaseEscrow | ReleaseSurplus | CancelUnfunded | RetrySettlement | ReturnExcessesBack | ResponseWalletAddress | TopUpTons
type EscrowBounce = AskToTransfer | AskToChangeOwnership | ServicePayment
fun onBouncedMessage(in:InMessageBounced){
    in.bouncedBody.skipBouncedPrefix();val msg=lazy EscrowBounce.fromSlice(in.bouncedBody);
    var s=EscrowStorage.fromCell(contract.getData());val t=s.terms.load();val c=s.config.load();
    match(msg){
        AskToTransfer=>{assert(s.wallet!=null && in.senderAddress==s.wallet! && msg.jettonAmount<=s.claimed) throw 710;s.claimed-=msg.jettonAmount;contract.setData(s.toCell());}
        AskToChangeOwnership=>{assert(t.asset!=null && in.senderAddress==t.asset! && t.kind==2 && s.claimed==1) throw 710;s.claimed=0;contract.setData(s.toCell());}
        ServicePayment=>{assert(s.phase==2 && in.senderAddress==c.treasury && msg.queryId==queryIdFor(c)) throw 710;s.phase=4;s.returnedFee=max(0,in.valueCoins-calculateGasFee(0,25000)) as coins;contract.setData(s.toCell());}
        else=>throw 703
    }
}
fun escrowPayment(s:EscrowStorage,credit:coins=0,incoming:coins=0){
    val c=s.config.load();val t=s.terms.load();val e=c.economics.load();
    val principalReserve=e.storageReserve+(t.kind==0?t.principal-s.claimed:0 as coins);
    // A retry may spend only the conservatively measured bounced payment and
    // the caller's new budget. Existing collateral and donations stay locked.
    val reserve=(incoming>0?max(principalReserve,contract.getOriginalBalance()-incoming+contract.getStorageDuePayment()-credit):principalReserve) as coins;
    reserveGramsOnBalance(reserve,RESERVE_MODE_EXACT_AMOUNT);
    if(e.serviceFee>0){val fee=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:c.treasury,value:e.serviceFee+e.recipientTopup,body:ServicePayment{queryId:queryIdFor(c),quoteId:c.quoteId}});fee.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);}
    val ack=createMessage({bounce:BounceMode.NoBounce,dest:c.identity.load().launcher,value:grams("0.015"),body:FactoryReceipt{queryId:queryIdFor(c)}});ack.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_IGNORE_ERRORS);
    val refund=createMessage({bounce:BounceMode.NoBounce,dest:c.creator,value:0,body:ReturnExcessesBack{queryId:queryIdFor(c)}});refund.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);
}
fun onInternalMessage(in:InMessage){
    if(in.body.isEmpty()){return;}val msg=lazy EscrowMessage.fromSlice(in.body);
    var s=EscrowStorage.fromCell(contract.getData());val c=s.config.load();val t=s.terms.load();val e=c.economics.load();
    match(msg){
        LaunchCreation=>{
            requireQuery(c,msg.queryId);assert(s.phase==0 && in.senderAddress==c.identity.load().launcher) throw 710;
            if(blockchain.now()>c.deadline){s.phase=3;contract.setData(s.toCell());refundAllToCreator(c);return;}
            assert(t.end>=t.cliff && t.cliff>=t.start && t.end>t.start && t.principal>0 && t.beneficiary.getWorkchain()==0 && in.valueCoins>=e.minimumLaunchValue+(t.kind==0?t.principal:0 as coins)) throw 705;
            var r=s.receipts.load();r.launchLt=in.createdLt;s.receipts=r.toCell();s.phase=t.kind==0?2:1;
            if(t.kind==0){s.receipts=settlementReceipt(s.receipts,in.senderAddress,in.createdLt,e.serviceFee);}
            contract.setData(s.toCell());if(t.kind==0){escrowPayment(s);}else if(t.kind==1||t.kind==3){
                assert(t.asset!=null) throw 724;
                val discover=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:t.asset!,value:grams("0.05"),body:RequestWalletAddress{queryId:queryIdFor(c),ownerAddress:contract.getAddress(),includeOwnerAddress:true}});discover.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
            }
        }
        ResponseWalletAddress=>{
            assert(s.phase==1 && t.asset!=null && in.senderAddress==t.asset! && msg.queryId==queryIdFor(c) && msg.jettonWalletAddress!=null && msg.ownerAddress!=null && msg.ownerAddress!.load()==contract.getAddress()) throw 710;
            s.wallet=msg.jettonWalletAddress;contract.setData(s.toCell());
        }
        TransferNotificationForRecipient=>{
            if(s.phase==3){
                assert(s.wallet!=null && in.senderAddress==s.wallet! && msg.transferInitiator!=null && msg.transferInitiator! == c.creator && in.valueCoins>=grams("0.15")) throw 710;
                val back=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:s.wallet!,value:grams("0.1"),body:AskToTransfer{queryId:msg.queryId,jettonAmount:msg.jettonAmount,transferRecipient:c.creator,sendExcessesTo:c.creator,customPayload:null,forwardTonAmount:1,forwardPayload:beginCell().storeUint(0,1).endCell().beginParse()}});back.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);return;
            }
            assert(s.phase==1 && (t.kind==1||t.kind==3) && s.wallet!=null && in.senderAddress==s.wallet! && msg.transferInitiator!=null && msg.transferInitiator! == c.creator && msg.queryId==queryIdFor(c) && msg.jettonAmount==t.principal) throw 710;
            assert(in.valueCoins>=grams("0.08")) throw 705;s.phase=2;s.receipts=settlementReceipt(s.receipts,in.senderAddress,in.createdLt,e.serviceFee);contract.setData(s.toCell());escrowPayment(s);
        }
        NotificationForNewOwner=>{
            if(s.phase==3){
                assert(t.kind==2 && t.asset!=null && in.senderAddress==t.asset! && msg.oldOwnerAddress==c.creator && in.valueCoins>=grams("0.15")) throw 710;
                val back=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:t.asset!,value:grams("0.1"),body:AskToChangeOwnership{queryId:msg.queryId,newOwnerAddress:c.creator,sendExcessesTo:c.creator,customPayload:null,forwardTonAmount:1,forwardPayload:beginCell().storeUint(0,1).endCell().beginParse()}});back.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);return;
            }
            assert(s.phase==1 && t.kind==2 && t.asset!=null && in.senderAddress==t.asset! && msg.oldOwnerAddress==c.creator && msg.queryId==queryIdFor(c) && in.valueCoins>=grams("0.08")) throw 710;
            s.phase=2;s.receipts=settlementReceipt(s.receipts,in.senderAddress,in.createdLt,e.serviceFee);contract.setData(s.toCell());escrowPayment(s);
        }
        ReleaseEscrow=>{
            if(s.phase==3){
                assert(t.kind==2 && t.asset!=null && in.senderAddress==c.creator && in.valueCoins>=grams("0.15")) throw 710;
                val recover=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:t.asset!,value:grams("0.1"),body:AskToChangeOwnership{queryId:msg.queryId,newOwnerAddress:c.creator,sendExcessesTo:c.creator,customPayload:null,forwardTonAmount:1,forwardPayload:beginCell().storeUint(0,1).endCell().beginParse()}});recover.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);return;
            }
            assert(s.phase==2 && blockchain.now()>=t.cliff && in.valueCoins>=grams("0.15")) throw 724;
            var vested:coins=blockchain.now()>=t.end?t.principal:(t.kind==2||t.kind==3?0 as coins:(t.principal*(blockchain.now()-t.start)/(t.end-t.start)) as coins);
            assert(vested>s.claimed) throw 724;val amount=vested-s.claimed;s.claimed=vested;contract.setData(s.toCell());
            reserveGramsOnBalance(max(e.storageReserve+(t.kind==0?t.principal-s.claimed:0 as coins),contract.getOriginalBalance()-in.valueCoins-(t.kind==0?amount:0 as coins)),RESERVE_MODE_EXACT_AMOUNT);
            if(t.kind==0){val release=createMessage({bounce:BounceMode.NoBounce,dest:t.beneficiary,value:amount,body:ReturnExcessesBack{queryId:msg.queryId}});release.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);}
            else if(t.kind==2){val release=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:t.asset!,value:grams("0.1"),body:AskToChangeOwnership{queryId:msg.queryId,newOwnerAddress:t.beneficiary,sendExcessesTo:t.beneficiary,customPayload:null,forwardTonAmount:1,forwardPayload:beginCell().storeUint(0,1).endCell().beginParse()}});release.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);}
            else{val release=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:s.wallet!,value:grams("0.1"),body:AskToTransfer{queryId:msg.queryId,jettonAmount:amount,transferRecipient:t.beneficiary,sendExcessesTo:t.beneficiary,customPayload:null,forwardTonAmount:1,forwardPayload:beginCell().storeUint(0,1).endCell().beginParse()}});release.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);}
            val excess=createMessage({bounce:BounceMode.NoBounce,dest:in.senderAddress,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});excess.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);
        }
        ReleaseSurplus=>{
            if(s.phase==3){
                if(msg.amount==0){assert(in.senderAddress==c.creator && in.valueCoins>=grams("0.05")) throw 710;reserveGramsOnBalance(e.storageReserve,RESERVE_MODE_EXACT_AMOUNT);val nativeRefund=createMessage({bounce:BounceMode.NoBounce,dest:c.creator,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});nativeRefund.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);return;}
                assert((t.kind==1||t.kind==3) && s.wallet!=null && in.senderAddress==c.creator && msg.amount>0 && in.valueCoins>=grams("0.15")) throw 710;
                val recover=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:s.wallet!,value:grams("0.1"),body:AskToTransfer{queryId:msg.queryId,jettonAmount:msg.amount,transferRecipient:c.creator,sendExcessesTo:c.creator,customPayload:null,forwardTonAmount:1,forwardPayload:beginCell().storeUint(0,1).endCell().beginParse()}});recover.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);return;
            }
            // External jetton wallets can return a failed downstream transfer to
            // the escrow wallet. Only the beneficiary may recover it, after all
            // principal has vested; never trust a supplied balance before end.
            assert(s.phase==2 && blockchain.now()>=t.end && in.senderAddress==t.beneficiary && in.valueCoins>=grams("0.15")) throw 710;
            if(t.kind==0||msg.amount==0){if(t.kind==0){s.claimed=t.principal;contract.setData(s.toCell());}reserveGramsOnBalance(e.storageReserve,RESERVE_MODE_EXACT_AMOUNT);val surplus=createMessage({bounce:BounceMode.NoBounce,dest:t.beneficiary,value:0,body:ReturnExcessesBack{queryId:msg.queryId}});surplus.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);}
            else{assert(t.kind!=2 && msg.amount>0) throw 724;val surplus=createMessage({bounce:BounceMode.Only256BitsOfBody,dest:s.wallet!,value:grams("0.1"),body:AskToTransfer{queryId:msg.queryId,jettonAmount:msg.amount,transferRecipient:t.beneficiary,sendExcessesTo:t.beneficiary,customPayload:null,forwardTonAmount:1,forwardPayload:beginCell().storeUint(0,1).endCell().beginParse()}});surplus.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_BOUNCE_ON_ACTION_FAIL);}
        }
        CancelUnfunded=>{assert(s.phase==1 && in.senderAddress==c.creator && blockchain.now()>c.deadline) throw 710;s.phase=3;contract.setData(s.toCell());
            reserveGramsOnBalance(e.storageReserve,RESERVE_MODE_EXACT_AMOUNT);
            val ack=createMessage({bounce:BounceMode.NoBounce,dest:c.identity.load().launcher,value:grams("0.015"),body:FactoryReceipt{queryId:queryIdFor(c)}});ack.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_IGNORE_ERRORS);
            val refund=createMessage({bounce:BounceMode.NoBounce,dest:c.creator,value:0,body:ReturnExcessesBack{queryId:queryIdFor(c)}});refund.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_IGNORE_ERRORS);
        }
        RetrySettlement=>{requireQuery(c,msg.queryId);assert(s.phase==4 && in.valueCoins>=grams("0.1")) throw 712;val credit=s.returnedFee;s.phase=2;s.returnedFee=0;s.receipts=settlementReceipt(s.receipts,in.senderAddress,in.createdLt,e.serviceFee);contract.setData(s.toCell());escrowPayment(s,credit,in.valueCoins);}
        ReturnExcessesBack=>{}
        TopUpTons=>{}
        else=>throw 703
    }
}
get fun get_escrow_data():cell{return contract.getData();}

